        var workers = [];
        for (var index = 0; index < LOCAL_RESOURCE_PUBLIC_CONCURRENCY; index++) workers.push(worker());
        await Promise.all(workers);
        status.public.running = false;
        if (failure) {
            status.public.state = 'error';
            status.public.stopped = true;
            setError(failure);
            scheduleRetry();
            emit();
            return false;
        }
