    strategy = validateGroupSpeakerStrategy(conv, raw);
    if (!getGroupSpeakerForMode(conv, strategy.mode)) throw new Error(strategy.mode === 'probability' ? t('group_strategy_zero_weights') : t('group_strategy_no_unmuted'));
