// 公共角色卡网格：渲染服务器卡片、加载状态和详情入口。
function renderPublicCards() {
    var isCatalog = activeLibraryTab === 'public' || activeLibraryTab === 'contributors';
    if (!isCatalog) {
        var hiddenSeriesGrid = document.getElementById('publicSeriesGrid');
        var hiddenCardsGrid = document.getElementById('publicCardsGrid');
        if (hiddenSeriesGrid) hiddenSeriesGrid.classList.add('hidden');
        if (hiddenCardsGrid) hiddenCardsGrid.classList.add('hidden');
        updatePublicLibraryChrome();
        return;
    }
    if (publicLibraryLevel === 'cards' && activePublicSeriesId) {
        renderPublicSeriesCards();
    } else {
        publicLibraryLevel = 'series';
        renderPublicSeriesFolders();
    }
    updatePublicLibraryChrome();
}

function renderLibraryGrids() {
    renderMyCards();
    renderPublicCards();
}
