function ensureHistoryLoadUI(container, conv, allMessages, currentStartIdx) {
    return syncChatHistoryLoadUi(container, conv, { startIdx: currentStartIdx });
}

/** 加载更多历史消息（增加窗口大小并重新渲染） */
