        var type = String.fromCharCode.apply(null, bytes.subarray(offset + 4, offset + 8));
        if (type === 'IEND') { parts.push(chunk, bytes.subarray(offset, offset + length + 12)); return new Blob(parts, { type: 'image/png' }); }
