// ==================== Initialize ====================
async function init() {
    cacheDom();
    await initializeStorageAndState();
    bindEvents();
    applyInitialLanguageState();
    applyTranslations();
    renderAll();
    showInitialLibraryView();
    updateStartupInputAvailability();
    await migrateActiveConversationFirstMessage();
    scheduleAnnouncementModal();
}

installAppDebugGlobals();
startApp();
